create table if not exists public.receivable_accounts(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete restrict,description text not null check(length(trim(description))>0),total_amount numeric(14,2) not null check(total_amount>0),opened_at date not null default current_date,due_date date,status text not null default 'open' check(status in ('open','paid','cancelled')),notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.receivable_payments alter column sale_id drop not null;alter table public.receivable_payments add column if not exists account_id uuid references public.receivable_accounts(id) on delete restrict;alter table public.receivable_payments drop constraint if exists receivable_payments_source_check;alter table public.receivable_payments add constraint receivable_payments_source_check check((sale_id is not null and account_id is null) or (sale_id is null and account_id is not null));
create index if not exists receivable_accounts_customer_date_idx on public.receivable_accounts(customer_id,opened_at desc);create index if not exists receivable_accounts_status_due_idx on public.receivable_accounts(status,due_date);create index if not exists receivable_payments_account_date_idx on public.receivable_payments(account_id,paid_at desc);
alter table public.receivable_accounts enable row level security;drop policy if exists "Active users read receivable accounts" on public.receivable_accounts;create policy "Active users read receivable accounts" on public.receivable_accounts for select to authenticated using(public.is_active_user());drop policy if exists "Staff manage receivable accounts" on public.receivable_accounts;create policy "Staff manage receivable accounts" on public.receivable_accounts for all to authenticated using(public.is_active_user() and public.has_role(array['owner','admin','cashier']::public.app_role[])) with check(public.is_active_user() and public.has_role(array['owner','admin','cashier']::public.app_role[]));drop policy if exists "Managers record receivable payments" on public.receivable_payments;create policy "Managers record receivable payments" on public.receivable_payments for insert to authenticated with check(public.is_active_user() and public.has_role(array['owner','admin','cashier']::public.app_role[]));grant select,insert,update,delete on public.receivable_accounts to authenticated;grant select,insert on public.receivable_payments to authenticated;
create or replace function public.register_receivable_account_payment(p_account_id uuid,p_amount numeric,p_method text,p_paid_at date default current_date,p_reference text default null,p_notes text default null,p_cash_session_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_payment uuid;v_total numeric(14,2);v_paid numeric(14,2);v_method public.payment_method;v_movement uuid;v_customer text;v_description text;begin
if v_user is null or not public.is_active_user() or not public.has_role(array['owner','admin','cashier']::public.app_role[]) then raise exception 'No tienes permisos para registrar abonos.';end if;if p_amount is null or p_amount<=0 then raise exception 'El abono debe ser mayor que cero.';end if;begin v_method:=p_method::public.payment_method;exception when others then raise exception 'Medio de pago no válido.';end;
select a.total_amount,c.full_name,a.description into v_total,v_customer,v_description from public.receivable_accounts a join public.customers c on c.id=a.customer_id where a.id=p_account_id and a.status='open' for update of a;if not found then raise exception 'La cuenta no existe o no está abierta.';end if;select coalesce(sum(amount),0) into v_paid from public.receivable_payments where account_id=p_account_id;if p_amount>v_total-v_paid then raise exception 'El abono supera el saldo pendiente.';end if;
if v_method='cash' then if p_cash_session_id is null or not exists(select 1 from public.cash_sessions where id=p_cash_session_id and closed_at is null) then raise exception 'Para registrar efectivo debes seleccionar una caja abierta.';end if;else p_cash_session_id:=null;end if;
insert into public.receivable_payments(sale_id,account_id,amount,method,paid_at,reference,notes,cash_session_id,created_by) values(null,p_account_id,p_amount,v_method,p_paid_at,p_reference,p_notes,p_cash_session_id,v_user) returning id into v_payment;
if v_method='cash' then insert into public.cash_movements(cash_session_id,kind,amount,category,description,reference,created_by) values(p_cash_session_id,'income',p_amount,'Abono de cartera','Abono de cuenta: '||v_customer||' · '||v_description,p_reference,v_user) returning id into v_movement;update public.receivable_payments set cash_movement_id=v_movement where id=v_payment;end if;if p_amount>=v_total-v_paid then update public.receivable_accounts set status='paid',updated_at=now() where id=p_account_id;end if;insert into public.audit_log(actor_id,action,entity,entity_id,details) values(v_user,'insert','receivable_payments',v_payment::text,jsonb_build_object('account_id',p_account_id,'amount',p_amount,'method',v_method,'paid_at',p_paid_at));return v_payment;end $$;grant execute on function public.register_receivable_account_payment(uuid,numeric,text,date,text,text,uuid) to authenticated;
create or replace function public.audit_receivable_account_changes() returns trigger language plpgsql security definer set search_path=public as $$ declare v_id text;v_details jsonb;begin if TG_OP='DELETE' then v_id:=old.id::text;v_details:=jsonb_build_object('old',to_jsonb(old));elsif TG_OP='UPDATE' then v_id:=new.id::text;v_details:=jsonb_build_object('old',to_jsonb(old),'new',to_jsonb(new));else v_id:=new.id::text;v_details:=jsonb_build_object('new',to_jsonb(new));end if;insert into public.audit_log(actor_id,action,entity,entity_id,details) values(auth.uid(),lower(TG_OP),TG_TABLE_NAME,v_id,v_details);if TG_OP='DELETE' then return old;else return new;end if;end $$;drop trigger if exists audit_receivable_accounts_changes on public.receivable_accounts;create trigger audit_receivable_accounts_changes after insert or update or delete on public.receivable_accounts for each row execute function public.audit_receivable_account_changes();